INSERT INTO lessons (level_id,lesson_key,sort_order,title,title_translation,description,primary_outcome_key,estimated_duration_sec,source_hash,status,metadata)
VALUES (@level_id,'EN-A1-L-0100',100,'Busy this week','این هفته سرم شلوغ است','با week درباره برنامه این هفته و هفته بعد طبیعی‌تر حرف بزن.','EN-A1-OUTCOME-0100',420,'b4d271e7140e5c44b86ae972022cf12163cdf6052b784ce867c7c0469761db8a','validated','{"outcomeFa":"week را در دو جمله کوتاه و طبیعی برای برنامه این هفته و هفته بعد به کار ببری.","scenarioFa":"لیو و لیام در کتابخانه درباره زمان مطالعه این هفته هماهنگ می‌کنند.","prerequisiteOutcomeKeys":["EN-A1-OUTCOME-0099"],"curriculum":{"startingKnowledge":"early_a1_spoken_core_and_recent_review","targetConstructions":[{"key":"EN-CONSTR-0100-WEEK","form":"I''m busy this week","meaningFa":"گفتن وضعیت برنامه در یک هفته مشخص"}],"supportLanguage":[{"form":"Are you free now?","meaningFa":"الان وقت داری؟"},{"form":"And next week?","meaningFa":"و هفته بعد؟"}],"assessmentBoundary":"Only the bounded A1 seven-day-period sense of week used in this Lesson is assessed.","transferPlan":{"mode":"same_lesson","intent":"Recombine the target from this week to next week in a second controlled context."},"story":{"arcKey":"EN-A1-LIBRARY","sceneKey":"EN-A1-FACTORY-SCENE-0100","learnerRoleKey":"liam","participants":["leo","liam"],"introducedCharacterKeys":[],"relationshipState":"already_known","dependsOnLessonKeys":["EN-A1-L-0095"],"continuesLessonKey":"EN-A1-L-0095","settingFa":"کتابخانه، کنار تقویم مطالعه","storyBeatFa":"لیو درباره زمان مطالعه می‌پرسد و لیام با week جواب می‌دهد."},"reviewLinks":[{"lessonKey":"EN-A1-L-0095","activityKeys":["A02"],"learningDemand":"retrieval","note":"Returning arc is spaced by 5 Lessons and the learner role rotates from Leo to Liam."}],"languageReference":{"specKey":"en-fa-A1-LESSON-SPEC-0100","specHash":"4d0bb8b0179334ea2402187e8a903f74e5df723d0814098122844b19e2ea39be","grammarTargetKeys":[],"reviewLexicalLemmas":[],"usageFallbacks":[{"query":"i''m busy this week","rationale":"Natural first-person schedule statement for the current week."},{"query":"i''m free next week","rationale":"Natural changed-week transfer about personal availability."},{"query":"busy this week","rationale":"Natural target-collocation window around week in a personal schedule statement."},{"query":"free next week","rationale":"Natural transfer collocation around week in a personal availability statement."}],"noNewGrammarReason":"Lexical-focus Lesson using familiar A1 time-reference patterns; no new grammar is claimed."},"pedagogyVersion":2},"pilot":false,"audioRequired":true,"humanEnglishAuditRequired":true,"dialogueRuntime":"guided_exchange","qualityStage":"model_reviewed_for_testing","qualityV2Remediated":true,"qualityV2RemediationVersion":1}')
ON DUPLICATE KEY UPDATE level_id=VALUES(level_id),sort_order=VALUES(sort_order),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),primary_outcome_key=VALUES(primary_outcome_key),estimated_duration_sec=VALUES(estimated_duration_sec),source_hash=VALUES(source_hash),status=VALUES(status),metadata=VALUES(metadata);
SET @lesson_id=(SELECT id FROM lessons WHERE level_id=@level_id AND lesson_key='EN-A1-L-0100' LIMIT 1);
DELETE FROM lesson_lexical_items WHERE lesson_id=@lesson_id;

-- Keep existing activities IDs; remove only keys absent from this Lesson source.
DELETE FROM activities WHERE lesson_id=@lesson_id AND activity_key NOT IN ('A02','A01','A03','A04','A05','A06');
SET @child_order_offset=(SELECT GREATEST(COALESCE(MAX(sort_order),0),6) FROM activities WHERE lesson_id=@lesson_id);
UPDATE activities SET sort_order=sort_order+@child_order_offset WHERE lesson_id=@lesson_id ORDER BY sort_order DESC;

-- Keep existing lesson_turns IDs; remove only keys absent from this Lesson source.
DELETE FROM lesson_turns WHERE lesson_id=@lesson_id AND turn_key NOT IN ('T01','T02','T03','T04');
SET @child_order_offset=(SELECT GREATEST(COALESCE(MAX(sort_order),0),4) FROM lesson_turns WHERE lesson_id=@lesson_id);
UPDATE lesson_turns SET sort_order=sort_order+@child_order_offset WHERE lesson_id=@lesson_id ORDER BY sort_order DESC;

